<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    ├──</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lodash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  →</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .pnpm/lodash@4.17.21/node_modules/lodash</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 符号链接</span></span>
